import type { Metadata } from "next";
import { getTranslations } from "next-intl/server";

import { getAuthSession } from "@intelligo-dev/auth";

import { Link } from "@/i18n/navigation";
import { AuthCard } from "@/components/auth/auth-card";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { ResendVerificationButton } from "@/components/auth/resend-verification-button";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("auth-email-verification");
  return {
    title: t("metadata.title"),
    description: t("metadata.description"),
  };
}

interface Props {
  searchParams: Promise<{ error?: string; email?: string }>;
}

/**
 * Better-Auth's `/verify-email` link handler (clicked from the emailed
 * link, not called from this page) redirects back here with `?error=CODE`
 * on an invalid/expired/unknown token, or with no query param at all —
 * plus a fresh session cookie — on success. That gives this page three
 * honestly distinguishable states without guessing: verified (a session
 * exists), failed (an `error` code came back), or still pending (neither
 * — the visitor hasn't clicked the link yet).
 */
function errorMessageFor(
  error: string | undefined,
  t: Awaited<ReturnType<typeof getTranslations>>
): string | null {
  if (!error) return null;
  const knownCodes = ["INVALID_TOKEN", "TOKEN_EXPIRED", "USER_NOT_FOUND"];
  const key = knownCodes.includes(error) ? error : "UNKNOWN";
  return t(`errors.${key}`);
}

export default async function VerifyEmailPage({ searchParams }: Props) {
  const { error, email } = await searchParams;
  const authSession = await getAuthSession();
  const t = await getTranslations("auth-email-verification");

  if (authSession?.user.emailVerified) {
    return (
      <AuthCard
        title={t("verifiedState.title")}
        description={t("verifiedState.description")}
      >
        <div className="space-y-4">
          <Alert>
            <AlertDescription>{t("verifiedState.message")}</AlertDescription>
          </Alert>
          <Link
            href="/dashboard"
            className="block text-center text-sm font-medium text-primary hover:text-primary/80"
          >
            {t("verifiedState.dashboardLink")}
          </Link>
        </div>
      </AuthCard>
    );
  }

  const errorMessage = errorMessageFor(error, t);

  return (
    <AuthCard
      title={errorMessage ? t("failedState.title") : t("pendingState.title")}
      description={errorMessage ?? t("pendingState.description")}
    >
      <div className="space-y-4">
        {errorMessage && (
          <Alert variant="destructive">
            <AlertDescription>{errorMessage}</AlertDescription>
          </Alert>
        )}

        <ResendVerificationButton email={email} />

        <div className="text-center">
          <Link
            href="/login"
            className="text-sm text-muted-foreground hover:text-primary"
          >
            {t("backToLogin")}
          </Link>
        </div>
      </div>
    </AuthCard>
  );
}

"use client";

/**
 * Client-side control for resending a verification email. Calls the
 * Better-Auth client SDK's `sendVerificationEmail` action directly — no
 * raw `fetch("/api/auth/*")`.
 *
 * The endpoint requires an `email` in the request body and works
 * whether or not the visitor has a session (Better-Auth answers with a
 * constant-time "if this email exists…" response either way, so it
 * never leaks whether an address is registered). When the page already
 * knows the address — passed in via `email`, e.g. from the signup
 * redirect's `?email=` search param — this renders just the button;
 * otherwise it asks for the address first.
 */

import { useState } from "react";
import { useTranslations } from "next-intl";

import { authClient } from "@intelligo-dev/auth/client";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Field, FieldLabel } from "@/components/ui/field";
import { Spinner } from "@/components/ui/spinner";

interface ResendVerificationButtonProps {
  email?: string;
}

export function ResendVerificationButton({
  email: knownEmail,
}: ResendVerificationButtonProps) {
  const t = useTranslations("auth-email-verification");
  const [email, setEmail] = useState(knownEmail ?? "");
  const [isResending, setIsResending] = useState(false);
  const [resendSuccess, setResendSuccess] = useState(false);
  const [resendError, setResendError] = useState<string | null>(null);

  async function handleResend() {
    if (!email) {
      setResendError(t("resend.errors.missingEmail"));
      return;
    }

    try {
      setIsResending(true);
      setResendError(null);
      setResendSuccess(false);

      const result = await authClient.sendVerificationEmail({
        email,
        callbackURL: "/verify-email",
      });

      if (result.error) {
        setResendError(result.error.message ?? t("resend.errors.unexpected"));
        return;
      }

      setResendSuccess(true);
    } catch (error) {
      console.error("Resend verification error:", error);
      setResendError(t("resend.errors.unexpected"));
    } finally {
      setIsResending(false);
    }
  }

  return (
    <div className="space-y-4">
      {!knownEmail && (
        <Field>
          <FieldLabel htmlFor="resend-email">
            {t("resend.emailLabel")}
          </FieldLabel>
          <Input
            id="resend-email"
            type="email"
            autoComplete="email"
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            disabled={isResending || resendSuccess}
            aria-invalid={resendError ? true : undefined}
            aria-describedby={resendError ? "resend-email-error" : undefined}
          />
        </Field>
      )}

      {resendSuccess && (
        <Alert>
          <AlertDescription>{t("resend.success")}</AlertDescription>
        </Alert>
      )}

      {resendError && (
        <Alert id="resend-email-error" variant="destructive">
          <AlertDescription>{resendError}</AlertDescription>
        </Alert>
      )}

      <Button
        type="button"
        variant="outline"
        className="w-full"
        onClick={handleResend}
        disabled={isResending || resendSuccess}
        aria-busy={isResending || undefined}
      >
        {isResending ? (
          <>
            <Spinner data-icon="inline-start" />
            {t("resend.sending")}
          </>
        ) : resendSuccess ? (
          t("resend.sent")
        ) : (
          t("resend.submit")
        )}
      </Button>
    </div>
  );
}

{
  "metadata": {
    "title": "Verify your email",
    "description": "Confirm your email address."
  },
  "verifiedState": {
    "title": "Email verified",
    "description": "Your email address has been confirmed",
    "message": "You're all set — your account is fully active.",
    "dashboardLink": "Go to dashboard"
  },
  "pendingState": {
    "title": "Verify your email",
    "description": "We've sent a verification link to your email. Click it to activate your account."
  },
  "failedState": {
    "title": "Verification failed"
  },
  "backToLogin": "Back to login",
  "errors": {
    "INVALID_TOKEN": "This verification link is invalid. Request a new one below.",
    "TOKEN_EXPIRED": "This verification link has expired. Request a new one below.",
    "USER_NOT_FOUND": "We couldn't find an account for this verification link.",
    "UNKNOWN": "This verification link could not be used. Request a new one below."
  },
  "resend": {
    "emailLabel": "Email",
    "submit": "Resend verification email",
    "sending": "Sending…",
    "sent": "Verification email sent",
    "success": "Verification email sent. Check your inbox.",
    "errors": {
      "missingEmail": "Enter your email address first.",
      "unexpected": "Failed to send verification email."
    }
  }
}
